/* V4.3 mobile city layer. It is a view/controller shell: server authority remains in client.js. */
(function(){'use strict';
 const fallback=[
  {id:'jiuquan',name:'酒泉生活門市',district:'大同區',short:'酒泉',x:0,z:-2.7},
  {id:'wanda',name:'萬大生活門市',district:'萬華區',short:'萬大',x:-12.3,z:39.3},
  {id:'dadaocheng',name:'大稻埕生活門市',district:'大同區',short:'大稻埕',x:-2.55,z:10.05},
  {id:'fuxingnan',name:'復興南生活門市',district:'大安區',short:'復興南',x:26.55,z:37.95},
  {id:'sanchuang',name:'三創生活門市',district:'中正區',short:'三創',x:15.15,z:21.15},
  {id:'hangzhounan',name:'杭州南生活門市',district:'大安區',short:'杭州南',x:6.9,z:36.3},
  {id:'yongji',name:'永吉生活門市',district:'信義區',short:'永吉',x:49.35,z:22.2},
  {id:'tonghua',name:'通化生活門市',district:'大安區',short:'通化',x:36,z:33.45},
  {id:'liuzhangli',name:'六張犁生活門市',district:'大安區',short:'六張犁',x:37.05,z:42.9}
 ];
 const landmarkFallback=[{id:'taipei101',name:'台北101',district:'信義區',x:45,z:35.85},{id:'shilin-night-market',name:'士林夜市',district:'士林區',x:-9,z:-18.15},{id:'ningxia-night-market',name:'寧夏夜市',district:'大同區',x:.75,z:12.6}];
 const landmarks=Array.isArray(window.North12BCityData?.landmarks)?window.North12BCityData.landmarks.map((item,i)=>{const base=landmarkFallback.find(x=>x.id===item.id)||landmarkFallback[i]||landmarkFallback[0],rawX=Number(item.x),rawZ=Number(item.z);return({...base,...item,x:Number.isFinite(rawX)?rawX*1.5:base.x,z:Number.isFinite(rawZ)?-2.7+(rawZ+2.7)*1.5:base.z});}):landmarkFallback;
 const tasks=[
  {id:'kpi',name:'KPI 戰報',desc:'查看示範 KPI 摘要',coins:15,icon:'K'},
  {id:'awards',name:'台獎中心',desc:'查看示範台獎資料',coins:15,icon:'金'},
  {id:'report',name:'今日回報',desc:'完成一筆示範回報',coins:30,icon:'回'},
  {id:'tradein',name:'舊換新',desc:'瀏覽示範換機流程',coins:20,icon:'換'},
  {id:'price',name:'手機獎金',desc:'查看示範手機獎金',coins:20,icon:'機'}
 ];
 const vehicleFallback=[{id:'scooter-mint',name:'薄荷機車',price:'價格待訂',priceStatus:'pending',gold:null,coins:0,currency:'personalGold',speed:'6.2'},{id:'car-mint',name:'薄荷汽車',price:'價格待訂',priceStatus:'pending',gold:null,coins:0,currency:'personalGold',speed:'8.2'},{id:'car-sun',name:'晴光汽車',price:'價格待訂',priceStatus:'pending',gold:null,coins:0,currency:'personalGold',speed:'9.4'},{id:'car-violet',name:'紫藤汽車',price:'價格待訂',priceStatus:'pending',gold:null,coins:0,currency:'personalGold',speed:'11'}];
 const root=document.body;
 let stores=Array.isArray(window.North12BCityData?.stores)?window.North12BCityData.stores.slice():fallback.slice();
 let mapData=window.North12BCityData||{stores};
 let state={zone:'jiuquan',mode:'walk',coins:null,gold:null,tasks:[],profile:null,formalLinks:{},access:{accountKind:'demo',businessBuildings:true,businessTasks:true,editStores:true}};
 let tab='map',open=false,refs={};
 const normStores=()=>stores.map((item,i)=>{const id=item.id||item.zone||fallback[i]?.id,base=fallback.find(f=>f.id===id)||fallback[i]||fallback[0],rawX=Number(item.x),rawZ=Number(item.z),hasRaw=Number.isFinite(rawX)&&Number.isFinite(rawZ),x=hasRaw&&Array.isArray(window.North12BCityData?.stores)?rawX*1.5:base.x,z=hasRaw&&Array.isArray(window.North12BCityData?.stores)?-2.7+(rawZ+2.7)*1.5:base.z;return({...base,...item,id,short:item.short||item.label||base.short,name:item.name||item.label||base.name,district:item.district||base.district,x,z});});
 const mapBounds={minX:-24,maxX:66,minZ:-24,maxZ:56};
 const mapPercent=(value,min,max)=>Math.max(4,Math.min(96,Math.round((Number(value)-min)/(max-min)*100)));
 const mapX=value=>mapPercent(value,mapBounds.minX,mapBounds.maxX);
 const mapZ=value=>mapPercent(value,mapBounds.minZ,mapBounds.maxZ);
 function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
 function emit(name,detail){window.dispatchEvent(new CustomEvent(name,{detail}));}
 function ensure(){if(document.querySelector('#city-open'))return;const button=document.createElement('button');button.id='city-open';button.className='city-launcher';button.type='button';button.setAttribute('aria-controls','city-drawer');button.setAttribute('aria-expanded','false');button.innerHTML='<span class="city-launcher-icon">台</span><span>城市導覽</span>';root.append(button);
  const drawer=document.createElement('aside');drawer.id='city-drawer';drawer.className='city-drawer';drawer.hidden=true;drawer.setAttribute('aria-label','台北小城導覽');drawer.innerHTML=`<div class="city-drawer-head"><div><span class="city-kicker">TAIPEI PLAY DISTRICT</span><h2>城市散步</h2><p id="city-location-note">遊戲街區 · 九家門市</p></div><button class="city-close" type="button" aria-label="關閉城市導覽">×</button></div><div class="city-tabs" role="tablist"><button type="button" data-city-tab="map" role="tab">城市地圖</button><button type="button" data-city-tab="travel" role="tab">前往門市</button><button type="button" data-city-tab="tasks" role="tab">今日任務</button><button type="button" data-city-tab="npc" role="tab">主管小幫手</button></div><div id="city-content"></div><div class="city-drawer-foot"><button class="city-work-sites" type="button" data-city-work-sites>工作入口 ↗</button><button type="button" data-city-shops>逛商店</button><button type="button" data-city-forest>山林入口／回城</button><button type="button" data-city-forest-photo>山林觀景拍照</button><button type="button" data-city-photo>拍城市紀念照</button><span id="city-wallet">金幣 — · 金牌 —</span><a id="city-formal-home" href="https://lian852456-dot.github.io/liamlu/home.html" target="_blank" rel="noopener">直接使用一般網站 ↗</a></div>`;root.append(drawer);const forestButton=document.createElement('button');forestButton.type='button';forestButton.id='forest-open';forestButton.className='forest-launcher';forestButton.textContent='森林漫步 →';forestButton.setAttribute('aria-label','步行前往森林漫步入口');forestButton.addEventListener('click',()=>emit('city-forest',{}));root.append(forestButton);refs={button,forestButton,drawer,content:drawer.querySelector('#city-content'),note:drawer.querySelector('#city-location-note'),wallet:drawer.querySelector('#city-wallet')};button.addEventListener('click',()=>setOpen(!open));drawer.querySelector('.city-close').addEventListener('click',()=>setOpen(false));drawer.querySelectorAll('[data-city-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.cityTab)));drawer.addEventListener('click',onClick);render();}
 function setOpen(v){open=!!v;if(!refs.drawer)return;refs.drawer.hidden=!open;refs.button.setAttribute('aria-expanded',String(open));refs.button.classList.toggle('selected',open);if(open)render();}
 function setTab(v){tab=['map','travel','tasks','npc'].includes(v)?v:'map';render();}
 function storeById(id){const canonical=id==='syntrend'?'sanchuang':id;return normStores().find(s=>s.id===canonical||s.id===id)||normStores()[0];}
 function current(){return storeById(state.zone);}
 function modeLabel(mode){return mode==='car'?'汽車':mode==='scooter'?'機車':'步行';}
 function eta(store,mode=state.mode){const centers=window.CozySceneRules?.storeCenters||{},from=centers[state.zone]||current(),to=centers[store.id]||store,distance=Math.hypot(to.x-from.x,to.z-from.z),speed=mode==='walk'?3.4:(Number(state.movementSpeed)||3.4);return Math.max(2,Math.round(distance/speed))+' 秒';}
 function renderMap(){const active=current(),items=normStores();return `<section class="city-panel city-map-panel"><div class="city-panel-title"><span>TAIPEI IN MINIATURE</span><strong>九家門市 · 行政區</strong></div><button type="button" class="city-overview-button" data-city-overview>俯瞰 3D 城市 ↗</button><div class="city-map-note"><span class="city-map-pin">●</span><span>原創台北方位遊戲地圖，保留大致位置與行政區；距離經過壓縮。</span></div><div class="city-map" role="list" aria-label="九家門市相對位置">${items.map((s,i)=>`<button class="city-marker ${s.id===active.id?'active':''}" type="button" data-city-zone="${esc(s.id)}" style="--mx:${mapX(s.x)}%;--mz:${mapZ(s.z)}%" title="${esc(s.name)}"><i>${i+1}</i><span>${esc(s.short||s.name)}</span></button>`).join('')}${landmarks.map(l=>`<div class="city-landmark" style="--mx:${mapX(l.x)}%;--mz:${mapZ(l.z)}%"><span>◆</span>${esc(l.name)}</div>`).join('')}</div><button type="button" class="city-forest-card" data-city-forest><strong>森林漫步 →</strong><span>西側溪谷入口 · 沿原街道步行前往</span></button><div class="city-store-list">${items.map(s=>`<button type="button" class="city-store-row ${s.id===active.id?'active':''}" data-city-zone="${esc(s.id)}"><span class="store-index">${String(items.indexOf(s)+1).padStart(2,'0')}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.district)} · ${s.id===active.id?'目前所在':'點選查看'}</small></span><b>→</b></button>`).join('')}</div></section>`;}
 function renderTravel(){const active=current(),selected=state.selectedDestination?storeById(state.selectedDestination):null;return `<section class="city-panel"><div class="city-panel-title"><span>MOVE THROUGH THE CITY</span><strong>到另一家門市</strong></div>${selected?`<div class="city-destination"><strong>${esc(selected.name)}</strong><small>${esc(selected.district)} · ${esc(selected.address||'台北遊戲街區')}</small></div>`:''}<p class="city-lead">沿街步行可看見路人、貓狗與其他玩家；交通工具只改變遊戲速度，仍可隨時下車步行。</p><div class="city-modes">${[['walk','步行','慢慢逛','標準'],['scooter','機車','輕快穿街','依裝備'],['car','汽車','快速跨區','依裝備']].map(([id,label,desc,speed])=>`<button type="button" class="city-mode ${state.mode===id?'active':''}" data-city-mode="${id}"><strong>${label}</strong><span>${desc}</span><b>${speed}</b></button>`).join('')}</div><div class="city-destination"><span>目前在</span><strong>${esc(active.name)}</strong><small>${esc(active.district)} · 選下方門市出發</small></div><div class="city-travel-list">${normStores().filter(s=>s.id!==active.id).map(s=>`<button type="button" data-city-zone="${esc(s.id)}" class="city-travel-row"><span><strong>${esc(s.name)}</strong><small>${esc(s.district)} · ${modeLabel(state.mode)}約 ${eta(s)}</small></span><b>出發 →</b></button>`).join('')}</div></section>`;}
 function taskStatus(id){const found=(state.tasks||[]).find(t=>t.id===id||t.task===id);return found?.status||'demo';}
 function renderTasks(){const catalogVehicles=(state.catalog||[]).filter(item=>item.category==='car').map(item=>{const owned=!!state.inventory?.some(row=>row.item_id===item.id);return{...item,id:item.id,name:item.name,owned,price:item.priceStatus==='pending'?'價格待訂':item.currency==='personalGold'?item.gold+' 本月個人金牌':(item.coins??0)+' 金幣',pending:item.priceStatus==='pending',locked:!owned&&(item.priceStatus==='pending'||(item.currency==='personalGold'&&!state.personalGold?.trusted)),speed:item.speed??'依裝備'};});const vehicles=catalogVehicles.length?catalogVehicles:vehicleFallback;if(state.access?.businessTasks===false)return `<section class="city-panel"><div class="city-panel-title"><span>COZY CITY WALK</span><strong>訪客探索</strong></div><p class="city-lead">訪客可以逛九家門市、使用商店與換裝，也能和主管及同伴互動；內部業務大樓與正式入口會由伺服器保護。</p><div class="city-task-tip">走近戶外主管即可聊天；角色、背包與遊戲資產會保存到這張訪客續玩卡。</div><div class="city-subpanel"><span class="city-subtitle">遊戲交通工具</span><small>購車價格待訂；已收藏車輛仍可繼續使用，未有價格前不開放購買。</small>${vehicles.map(v=>`<div class="city-vehicle-row"><span><strong>${esc(v.name)}</strong><small>${esc(v.speed)} · ${v.price}</small></span><button type="button" data-city-vehicle="${esc(v.id)}" ${v.locked?'disabled':''}>${v.owned?'已收藏／裝備':v.pending?'價格待訂，暫不開放購買':v.locked?'待本人金牌對應':'購買／裝備'}</button></div>`).join('')}</div><div class="city-subpanel city-exchange-box"><span class="city-subtitle">金牌兌換預覽</span><small>訪客沒有正式金牌；遊戲商店仍可使用遊戲金幣。</small></div></section>`;return `<section class="city-panel"><div class="city-panel-title"><span>DAILY CITY ROUTE</span><strong>今天的功能大樓</strong></div><p class="city-lead">每個入口都只開啟隔離試玩示範；正式業務頁仍依原有權限處理。</p><div class="city-task-grid">${tasks.map(t=>{const status=taskStatus(t.id),done=status==='claimed'||status==='complete',coins=(state.tasks||[]).find(x=>(x.id||x.task)===t.id)?.coins??t.coins;return `<button type="button" class="city-task-card ${done?'done':''}" data-city-task="${t.id}"><i>${t.icon}</i><span><strong>${t.name}</strong><small>${t.desc}</small></span><b>${done?'已完成':'+'+coins}</b></button>`;}).join('')}</div><div class="city-task-tip">提示：同一任務每天只能領一次，重開頁面不會重複發獎。</div><div class="city-subpanel"><span class="city-subtitle">遊戲交通工具</span><small>購車價格待訂；已收藏車輛仍可繼續使用，未有價格前不開放購買。</small>${vehicles.map(v=>`<div class="city-vehicle-row"><span><strong>${esc(v.name)}</strong><small>${esc(v.speed)} · ${v.price}</small></span><button type="button" data-city-vehicle="${esc(v.id)}" ${v.locked?'disabled':''}>${v.owned?'已收藏／裝備':v.pending?'價格待訂，暫不開放購買':v.locked?'待本人金牌對應':'購買／裝備'}</button></div>`).join('')}</div><div class="city-subpanel city-exchange-box"><span class="city-subtitle">金牌兌換預覽</span><small>試玩規則：1 枚遊戲金牌 = 50 金幣；確認後才送出。</small><div class="city-exchange-line"><input id="city-gold-input" type="number" min="1" step="1" value="1" aria-label="要兌換的遊戲金牌數量"><span>枚 → <strong id="city-gold-preview">50</strong> 金幣</span><button type="button" data-city-exchange>確認兌換</button></div></div></section>`;}
 const answers={welcome:'我是蔚榮的城市助理，AI／遊戲角色，固定問答，不代表真人主管。我只提供已確認的試玩規則與入口提示。正式 KPI、台獎與管理指令請從原有受保護入口查看。',task:'到功能大樓或「今日任務」選擇示範內容，完成查看後即可領當日金幣；同一天每項只領一次。',travel:'可用步行、機車或汽車前往九家門市。交通是遊戲化速度參數，門市內的共同布置仍以同店權限為準。',layout:'進入同一家門市後，從生活手帳開啟共同布置；同店帳號可放置與拖曳，跨店來訪者只能參觀。',gold:'試玩商店顯示的是遊戲資產。1 枚遊戲金牌可換 50 金幣，先看預覽再確認。正式績效金牌不會由本遊戲發放。',unknown:'這個問題沒有已確認的試玩答案；我不會猜測或捏造正式資料，請改走正式入口查詢。'};
 function renderNpc(){const links=state.access?.businessBuildings===false?{}:(state.formalLinks||{});return `<section class="city-panel"><div class="city-panel-title"><span>MEET IN THE NEIGHBOURHOOD</span><strong>蔚榮主管在街上散步</strong></div><div class="city-supervisor"><div class="supervisor-avatar">榮</div><div><strong>蔚榮主管</strong><small>小城遊戲分身 · 九店與街角走訪</small></div></div><p class="city-lead">沿街走近主管，點人物或名字就能聊聊。可以自由輸入問題，詢問門市位置、任務、金幣與自己的遊戲物品；回答會附上依據。</p><p class="city-lead">主管會在戶外巡走，走近就能聊聊。</p><p class="city-task-tip">提問並讀完回答後，每天可領 5 枚遊戲金幣。主管會停下來聊天，結束後繼續散步。</p><p class="city-lead">未有依據的問題會說明無法確認；正式業績與管理指令請使用原有受保護入口。</p>${Object.entries(links).filter(([,url])=>url).map(([label,url])=>`<a class="city-formal-link" href="${esc(url)}" target="_blank" rel="noopener">前往${esc(({operations:'智慧營運中心',report:'每日回報',kpi:'KPI 戰報',awards:'台獎',tradein:'舊換新',price:'手機獎金'})[label]||label)}正式入口 ↗</a>`).join('')}</section>`;}

 function render(){if(!refs.content)return;const tabHtml=tab==='map'?renderMap():tab==='travel'?renderTravel():tab==='tasks'?renderTasks():renderNpc();refs.content.innerHTML=tabHtml;const active=current();refs.note.textContent='遊戲街區 · '+(active.name||'九家門市')+' · '+(active.district||'台北市');refs.wallet.textContent='金幣 '+(state.coins==null?'—':state.coins)+' · 遊戲金牌 '+(state.gold==null?'—':state.gold);const formalHome=document.querySelector('#city-formal-home');if(formalHome)formalHome.hidden=state.access?.businessBuildings===false;}
 function onClick(e){if(e.target.closest('[data-city-forest-photo]')){emit('city-forest-photo',{});return;}if(e.target.closest('[data-city-forest]')){emit('city-forest',{});return;}if(e.target.closest('[data-city-shops]')){emit('city-shops',{});return;}if(e.target.closest('[data-city-photo]')){emit('city-photo',{});return;}if(e.target.closest('[data-city-work-sites]')){emit('city-work-sites',{});return;}if(e.target.closest('[data-city-supervisor-find]')){emit('city-supervisor-find',{});return;}if(e.target.closest('[data-city-overview]')){emit('city-overview',{});return;}const zone=e.target.closest('[data-city-zone]');if(zone){const id=zone.dataset.cityZone;if(tab==='map'){state.selectedDestination=id;setTab('travel');return;}if(id===state.zone){setTab('travel');return;}const mode=state.mode;emit('city-travel',{zone:id,mode,source:'city-ui'});return;}const mode=e.target.closest('[data-city-mode]');if(mode){state.mode=mode.dataset.cityMode;emit('city-transport',{mode:state.mode,source:'city-ui'});render();return;}const task=e.target.closest('[data-city-task]');if(task){emit('city-task',{taskId:task.dataset.cityTask,source:'city-ui'});return;}const exchange=e.target.closest('[data-city-exchange]');if(exchange){const input=refs.content.querySelector('#city-gold-input'),gold=Math.max(1,Math.floor(Number(input?.value)||1));emit('city-exchange',{gold,coins:gold*50,source:'city-ui'});return;}const vehicle=e.target.closest('[data-city-vehicle]');if(vehicle){emit('city-equip-vehicle',{itemId:vehicle.dataset.cityVehicle,source:'city-ui'});return;}const q=e.target.closest('[data-city-question]');if(q){const answer=document.querySelector('#city-answer');if(answer)answer.textContent=answers[q.dataset.cityQuestion]||answers.welcome;emit('city-npc',{topic:q.dataset.cityQuestion,source:'city-ui'});}}
 function setState(next={}){if(refs.forestButton){const inForest=next.scene==='forest'||next.pose?.scene==='forest';if(next.scene||next.pose?.scene)refs.forestButton.textContent=inForest?'沿步道回小城 →':'森林漫步 →';}state={...state,...next,access:{...state.access,...(next.access||{})}};if(next.wallet){if(next.coins==null)state.coins=next.wallet.coins;if(next.gold==null)state.gold=next.wallet.gold;}if(next.stores&&Array.isArray(next.stores))stores=next.stores.slice();if(next.zone)state.zone=next.zone==='syntrend'?'sanchuang':next.zone;if(refs.content)render();}
 function setMapData(next={}){mapData={...mapData,...next};if(Array.isArray(next.stores)){stores=next.stores.slice();}if(refs.content)render();}
 window.addEventListener('city-npc',event=>{setOpen(true);setTab('npc');const topic=event.detail?.topic||'welcome';setTimeout(()=>{const answer=document.querySelector('#city-answer');if(answer)answer.textContent=answers[topic]||answers.unknown;},0);});
 ensure();
 window.CityUI={setState,setMapData,setOpen,setTab,getState:()=>({...state,stores:normStores(),landmarks:landmarks.slice()}),stores:()=>normStores()};
})();
